from hypothesis import strategies as st


@st.composite
def gen(draw):
    q = draw(st.integers(1, 10))
    queries = []
    for _ in range(q):
        kind = draw(st.sampled_from([1, 2, 3]))
        if kind == 1:
            queries.append("1")
        elif kind == 2:
            t = draw(st.one_of(st.integers(1, 3), st.integers(1, 10**9)))
            queries.append(f"2 {t}")
        else:
            h = draw(st.one_of(st.integers(1, 10), st.integers(1, 10**9)))
            queries.append(f"3 {h}")
    if not any(x.startswith("3") for x in queries):
        h = draw(st.integers(1, 10))
        queries[-1] = f"3 {h}"
    return f"{q}\n" + "\n".join(queries) + "\n"


def validate(inp):
    try:
        lines = inp.rstrip("\n").split("\n")
        q = int(lines[0])
        if not (1 <= q <= 2 * 10**5):
            return False
        if len(lines) != q + 1:
            return False
        has3 = False
        for line in lines[1:]:
            tok = line.split()
            if not tok:
                return False
            if tok[0] == "1":
                if len(tok) != 1:
                    return False
            elif tok[0] == "2":
                if len(tok) != 2:
                    return False
                t = int(tok[1])
                if not (1 <= t <= 10**9):
                    return False
            elif tok[0] == "3":
                if len(tok) != 2:
                    return False
                h = int(tok[1])
                if not (1 <= h <= 10**9):
                    return False
                has3 = True
            else:
                return False
        return has3
    except Exception:
        return False


def ref(inp):
    lines = inp.rstrip("\n").split("\n")
    q = int(lines[0])
    plants = []  # heights of existing plants, simulated literally
    out = []
    for i in range(1, q + 1):
        tok = lines[i].split()
        if tok[0] == "1":
            plants.append(0)
        elif tok[0] == "2":
            t = int(tok[1])
            plants = [p + t for p in plants]
        else:
            h = int(tok[1])
            cnt = sum(1 for p in plants if p >= h)
            plants = [p for p in plants if p < h]
            out.append(str(cnt))
    return "\n".join(out) + "\n"
